import json
import sqlite3

STEPS = ["install", "tutorial_complete", "first_match", "purchase"]

con = sqlite3.connect("analytics.db")

# Drop test accounts and events from unknown players (METRICS.md line 5).
users = {}
for uid, platform, is_test in con.execute("SELECT user_id, platform, is_test FROM users"):
    if not is_test:
        users[uid] = platform

events = {}
unknown = 0
for uid, name, ts in con.execute("SELECT user_id, name, ts FROM events"):
    if uid not in users or name not in STEPS:
        continue
    events.setdefault(uid, []).append((name, ts))

# A step counts only at/after the previous step's valid time; time = first valid occurrence.
def funnel_times(uid):
    evs = sorted(events.get(uid, []), key=lambda e: e[1])
    times = []
    for step in STEPS:
        t = None
        for name, ts in evs:
            if name != step:
                continue
            if not times or ts >= times[-1]:
                t = ts
                break
        if t is None:
            break
        times.append(t)
    return times

platforms = sorted(set(users.values()))
counts = {p: {s: 0 for s in STEPS} for p in platforms}
for uid, platform in users.items():
    for step, _ in zip(STEPS, funnel_times(uid)):
        counts[platform][step] += 1

result = {"funnel": {}, "biggest_drop": {}}
for p in platforms:
    result["funnel"][p] = {s: counts[p][s] for s in STEPS}
    best_step, best_conv = None, None
    for prev, step in zip(STEPS, STEPS[1:]):
        if counts[p][prev] == 0:
            continue
        conv = counts[p][step] / counts[p][prev]
        if best_conv is None or conv < best_conv:
            best_step, best_conv = step, conv
    result["biggest_drop"][p] = best_step
    print(p, result["funnel"][p],
          {step: round(counts[p][step] / counts[p][prev], 3)
           for prev, step in zip(STEPS, STEPS[1:]) if counts[p][prev]})

with open("result.json", "w", encoding="utf-8") as f:
    json.dump(result, f, indent=2)
print("test users:", con.execute("SELECT COUNT(*) FROM users WHERE is_test").fetchone()[0])
print("events from unknown players:",
      con.execute("SELECT COUNT(*) FROM events WHERE user_id NOT IN (SELECT user_id FROM users)").fetchone()[0])
